void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
int main(){try{auto dir=std::filesystem::temp_directory_path()/new_device_id();auto p=dir/"settings.json";Core c(p);c.start();auto id=c.settings.device_id;check(id.size()==36,"uuid");c.settings.hotkey="F8";c.settings.ui_scale=125;c.settings.notifications=false;c.save();c.stop();c.start();check(c.settings.device_id==id&&c.settings.hotkey=="F8"&&c.settings.ui_scale==125&&!c.settings.notifications,"restart");check(c.input.open(),"initial open"); check(c.input.key(true,"Insert","Insert")&&!c.input.open(),"Insert closes"); c.input.key(false,"Insert","Insert"); check(c.input.key(true,"Insert","Insert")&&c.input.open(),"Insert opens"); c.input.key(false,"Insert","Insert");check(c.input.key(true,"F8","F8")&&!c.input.open(),"toggle");check(!c.input.key(true,"F8","F8"),"repeat");c.input.key(false,"F8","F8");check(c.input.key(true,"F8","F8")&&c.input.open(),"toggle back");c.nav.select(Screen::Items);check(c.nav.current()==Screen::Items&&c.state(Screen::Items)==ViewState::NotConnected,"not connected");check(c.state(Screen::License)==ViewState::Offline,"offline");check(!c.license.permits(),"fail closed");HttpResponse ok{200,R"({"device_id":"abc","license_id":42,"platform":"hassle_rp_2","status":"active","server_time":"2026-01-01T00:00:00Z","expires_at":"2026-01-02T00:00:00Z"})","",false};check(c.license.apply_v2(ok)&&!c.license.permits(),"v2 parsed, command access remains disabled");c.license.offline();check(!c.license.permits(),"offline revoke");ok.body=R"({"device_id":"abc","license_id":42,"platform":"hassle_rp_2","status":"active","server_time":"2026-01-02T00:00:00Z","expires_at":"2026-01-02T00:00:00Z"})";check(!c.license.apply_v2(ok),"expired");ok.body=R"({"device_id":"abc","license_id":42,"platform":"hassle_rp_2","status":"active","server_time":"2026-01-01T00:00:00Z","expires_at":"2026-01-01T00:00:01Z"})";check(c.license.apply_v2(ok)&&c.license.online(),"fresh indication");std::this_thread::sleep_for(std::chrono::milliseconds(1100));check(!c.license.online()&&!c.license.permits(),"expired indication"); for(auto s:{ViewState::Loading,ViewState::Empty,ViewState::Success,ViewState::Error,ViewState::Offline,ViewState::Disabled,ViewState::NotConnected})check(std::string(state_name(s))!="", "state label");check(!c.license.apply_v2(HttpResponse{200,R"({"device_id":"abc","status":"active"})","",false}),"v1 not entitlement");auto a=adapters();check(a.size()==2&&!a[0]->connected()&&!a[1]->connected(),"disabled adapters");c.reset();check(c.settings.device_id==id&&c.settings.hotkey=="Insert"&&c.settings.notifications,"reset");auto vault=make_vault(dir/"vault");
#ifndef _WIN32
bool rejected=false;try{vault->save("this-is-not-a-real-credential");}catch(...){rejected=true;}check(rejected&&!std::filesystem::exists(dir/"vault"),"vault fail closed");
#else
const std::string secret="windows-test-value-not-real-credential";vault->save(secret);vault.reset();vault=make_vault(dir/"vault");check(vault->load()==secret,"DPAPI restart");{std::ifstream raw(dir/"vault",std::ios::binary);std::string encrypted((std::istreambuf_iterator<char>(raw)),{});check(encrypted.find(secret)==std::string::npos,"plaintext vault");}{std::ofstream broken(dir/"vault",std::ios::binary|std::ios::trunc);broken<<"corrupt";}bool failed=false;try{vault->load();}catch(...){failed=true;}check(failed,"corrupt vault should fail");vault->erase();
#endif
Logger logger(dir/"log");logger.event(LogCode::NetworkError);std::ifstream f(dir/"log");std::string l((std::istreambuf_iterator<char>(f)),{});f.close();check(l=="NETWORK_ERROR\n","logger allowlist");{std::ofstream f2(p);f2<<"bad json";}bool corrupt=false;try{SettingsStore(p).load();}catch(...){corrupt=true;}check(corrupt&&std::filesystem::exists(p),"invalid retained");std::filesystem::remove_all(dir);std::cout<<"Core tests passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
